function allowance(){return state.agreement.base+(state.agreement.conditionMet?state.agreement.bonus:0)}
function render(){$('#app').innerHTML=`<div class="grid"><div>${panel('先听见彼此，再写下约定',`<form id="agreement" class="stack"><div class="fields">${field('孩子希望 / 分钟','child','number',state.agreement.child,'required min="0" max="240"')}${field('家长希望 / 分钟','parent','number',state.agreement.parent,'required min="0" max="240"')}</div><p class="notice">讨论起点：${Math.round((state.agreement.child+state.agreement.parent)/2)} 分钟。这只是两方输入的中间值，需要共同确认。</p><div class="fields">${field('共同同意的基础时长','base','number',state.agreement.base,'required min="0" max="240"')}${field('完成约定后增加 / 分钟','bonus','number',state.agreement.bonus,'required min="0" max="60"')}</div>${field('双方同意的前置条件','condition','text',state.agreement.condition,'required maxlength="80"')}<label class="checkline"><input type="checkbox" name="conditionMet" ${state.agreement.conditionMet?'checked':''}>今天已完成前置条件</label><button class="primary">共同确认约定</button></form>`)}${panel('今天的复盘',`<form id="review" class="stack">${field('实际使用 / 分钟','actual','number','','required min="0" max="1440"')}<label>下次想如何调整<textarea name="note" required maxlength="200"></textarea></label><button>记录复盘</button></form>`)}</div><div>${panel('我们的共同约定',`<span class="tag">家庭讨论版 · 非设备控制</span><div style="font:64px Georgia;margin:20px 0">${allowance()}<small style="font-size:18px"> 分钟</small></div><p>${esc(state.agreement.condition)}：${state.agreement.conditionMet?'已完成':'尚未完成'}。</p><p>基础 ${state.agreement.base} 分钟 + 条件奖励 ${state.agreement.conditionMet?state.agreement.bonus:0} 分钟</p>`,'tint')}${panel('复盘记录',state.reviews.slice().reverse().map(x=>`<div class="item"><div><strong>${x.date} · 实际 ${x.actual} 分钟</strong><p>当时约定 ${x.allowed} 分钟 · ${x.actual>x.allowed?'超过约定，重新讨论':'在约定内'}</p><p>${esc(x.note)}</p></div></div>`).join('')||empty())}</div></div>`;
form('agreement',v=>{state.agreement={...v,child:+v.child,parent:+v.parent,base:+v.base,bonus:+v.bonus,conditionMet:v.conditionMet==='on'};commit();toast('约定已保存')});form('review',v=>{state.reviews.push({...v,actual:+v.actual,allowed:allowance(),date:today()});commit()})}render();
